pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PoCGame} from "../src/PoCGame.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PoCGame c;

    function setUp() public {
        c = new PoCGame(address(this), 0);
    }

    function _test(uint256 amount) internal {
        vm.assume(amount > 0);
        try c.AdjustDifficulty(amount) {} catch { return; }
        uint256 diff;
        try c.currentDifficulty() returns (uint256 __r) { diff = __r; } catch { return; }
        assertTrue(diff > 0);
    }

    function testFuzz_test(uint256 amount) public {
        _test(amount);
    }

    receive() external payable {}
}
